import {Heading} from '@primer/react'
import {clsx} from 'clsx'
import type {FC, ReactNode} from 'react'

import styles from './Title.module.css'

type TitleProps = {
  children: ReactNode
  showBorder?: boolean
  page?: string
  className?: string
}

export const Title: FC<TitleProps> = ({children, page, showBorder = true, className}) => {
  return (
    <Heading
      as="h2"
      id={`issue-types-heading${page ? `-${page}` : ''}`}
      className={clsx(styles.TitleHeading, showBorder && styles.TitleBorder, className)}
    >
      {children}
    </Heading>
  )
}
