import {mainQuery} from '@github-ui/react-core/future/main-query'

import {issueTypesSettingsAppBuilder} from '../config/app-builder'
import type {IssueType} from '../types/issue-type'

export type IssueTypesSettingsIndexResponse = {
  organization: {
    id: string
    login: string
  }
  issueTypes: IssueType[]
  pinnedIssueFieldsEnabled: boolean
}

export const issueTypesSettingsIndexRouteId = 'issueTypesSettingsIndexRoute'
export const issueTypesSettingsIndexRoute = issueTypesSettingsAppBuilder.createQueryRouteConfig(
  issueTypesSettingsIndexRouteId,
  {
    path: '/organizations/:organization_id/settings/issue-types',
    queries: [mainQuery<IssueTypesSettingsIndexResponse>()],
  },
)
