import {AnalyticsProvider} from '@github-ui/analytics-provider'
import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {ssrSafeWindow} from '@github-ui/ssr-utils'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import type {ColorName} from '@github-ui/use-named-color'
import {Link} from '@primer/react'
import {useCallback, useMemo, useState} from 'react'

import {PinnedIssueFields} from '../components/PinnedIssueFields'
import {Title} from '../components/Title'
import {TypeColor} from '../components/TypeColor'
import {TypeDescription} from '../components/TypeDescription'
import {TypeName} from '../components/TypeName'
import {TypeSubmissionButtons} from '../components/TypeSubmissionButtons'
import {ORGANIZATION_ISSUE_TYPES_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import {useInputFieldsErrors} from '../hooks/use-input-fields-errors'
import {useIssueTypesAnalytics} from '../hooks/use-issue-types-analytics'
import {
  type CreateIssueTypeMutationInput,
  type CreateIssueTypeMutationResult,
  useCreateIssueTypeMutation,
} from '../mutations/create-issue-type-mutation'
import {formatError} from '../utils'
import {type IssueTypesSettingsNewResponse, issueTypesSettingsNewRoute} from './new-route'
import styles from './OrganizationIssueTypesSettingsCreate.module.css'

export function OrganizationIssueTypesSettingsCreate() {
  const {data: preloadedData} = useRouteQuery(issueTypesSettingsNewRoute, 'mainQuery')
  const analyticsMetadata = {owner: preloadedData.organization.login ?? ''}

  return (
    <AnalyticsProvider appName="issue_types" category="create" metadata={analyticsMetadata}>
      <OrganizationIssueTypesSettingsCreateInternal preloadedData={preloadedData} />
    </AnalyticsProvider>
  )
}

function OrganizationIssueTypesSettingsCreateInternal({preloadedData}: {preloadedData: IssueTypesSettingsNewResponse}) {
  const {
    organization: {login: owner},
    issueTypes,
  } = preloadedData
  const {addToast} = useToastContext()
  const [name, setName] = useState<string>('')
  const [description, setDescription] = useState<string>('')
  const [color, setColor] = useState<ColorName>('GRAY')
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false)
  const pinnedIssueFieldsEnabled = preloadedData.pinnedIssueFieldsEnabled

  const [pinnedIssueFields, setPinnedIssueFields] = useState<IssueField[]>([])

  const {sendIssueTypesAnalyticsEvent} = useIssueTypesAnalytics()

  const existingIssueTypeNames = useMemo(() => {
    return (issueTypes || []).map(i => i.name) ?? []
  }, [issueTypes])

  const {
    typeNameRef,
    typeDescriptionRef,
    nameError,
    setNameError,
    descriptionError,
    setDescriptionError,
    setShouldFocusError,
    validate,
  } = useInputFieldsErrors(existingIssueTypeNames)

  const handleCancel = () => {
    if (ssrSafeWindow) {
      ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types`
    }
  }

  const createMutation = useCreateIssueTypeMutation({
    owner,
    onSuccess: (result: CreateIssueTypeMutationResult) => {
      if ('errors' in result && result.errors.length > 0) {
        result.errors.map(e => {
          reportError(formatError('CreateIssueType', e))
          if (e.startsWith('Name')) {
            setNameError(e)
          } else if (e.startsWith('Description')) {
            setDescriptionError(e)
          } else if (e.startsWith('Maximum')) {
            // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
            addToast({
              type: 'error',
              message: e,
            })
          }
        })
      } else {
        if (ssrSafeWindow) {
          ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types`
          return
        }
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'success',
          message: Resources.creatingIssueTypeSuccess,
        })
      }
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: Resources.creatingIssueTypeError,
      })
      setIsSubmitting(false)
    },
  })

  const handleCreate = useCallback(() => {
    const valid = validate()

    if (!valid) {
      setShouldFocusError(true)
      return
    }

    const mutationInput: CreateIssueTypeMutationInput = {
      name,
      description,
      color,
      isEnabled: true,
      // not providing issue type as it will be set to custom by default on the backend and the four default types get created by enabling them, not by going to the create page
    }

    sendIssueTypesAnalyticsEvent('org_issue_type.create', 'ORG_ISSUE_TYPE_CREATE_BUTTON')
    setIsSubmitting(true)

    createMutation?.mutateAsync({
      ...mutationInput,
      pinnedIssueFieldIds: pinnedIssueFields.map(f => f.id),
    })
  }, [
    validate,
    name,
    description,
    color,
    sendIssueTypesAnalyticsEvent,
    setShouldFocusError,
    createMutation,
    pinnedIssueFields,
  ])

  return (
    <div>
      <Title page="create">
        <Link href={`/organizations/${owner}/settings/issue-types`}>{Resources.settingsPageHeader}</Link>
        {` / ${Resources.newTitle}`}
      </Title>
      <div className={styles.formContainer}>
        {/* Hide the form if the ORGANIZATION_ISSUE_TYPES_LIMIT is reached */}
        {issueTypes?.length === ORGANIZATION_ISSUE_TYPES_LIMIT ? (
          <div className={styles.limitReachedContainer}>
            <span className={styles.limitReachedHeading}>You have reached the maximum number of issue types</span>
            <span className={styles.limitReachedInstructions}>
              To create a new one, please remove an existing type.
            </span>
          </div>
        ) : (
          <>
            <TypeName
              disabled={isSubmitting}
              name={name}
              setName={setName}
              error={nameError}
              setError={setNameError}
              ref={typeNameRef}
            />
            <TypeDescription
              disabled={isSubmitting}
              description={description}
              setDescription={setDescription}
              error={descriptionError}
              setError={setDescriptionError}
              ref={typeDescriptionRef}
            />
            <TypeColor color={color} setColor={setColor} />
            {pinnedIssueFieldsEnabled && (
              <PinnedIssueFields
                owner={owner}
                pinnedIssueFields={pinnedIssueFields}
                setPinnedIssueFields={setPinnedIssueFields}
              />
            )}
            <TypeSubmissionButtons
              disabled={isSubmitting}
              confirmLabel={Resources.saveCreatedIssueTypeButton}
              onCancel={handleCancel}
              onConfirm={handleCreate}
            />
          </>
        )}
      </div>
    </div>
  )
}
