import {CheckIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'

import {Resources} from '../constants/strings'
import styles from './TypeSubmissionButtons.module.css'

type TypeSubmissionButtonsProps = {
  disabled?: boolean
  confirmLabel: string
  cancelLabel?: string
  onCancel: () => void
  onConfirm: () => void
  changesSaved?: boolean
  ref?: React.Ref<HTMLDivElement>
}

export function TypeSubmissionButtons({
  ref: forwardedRef,
  disabled = false,
  onCancel,
  onConfirm,
  cancelLabel = Resources.cancelButton,
  confirmLabel,
  changesSaved = false,
}: TypeSubmissionButtonsProps) {
  return (
    <div className={styles.buttonContainer}>
      <Button variant="primary" onClick={onConfirm} data-testid="issue-type-confirm-button" disabled={disabled}>
        {confirmLabel}
      </Button>
      <Button onClick={onCancel} data-testid="issue-type-cancel-button" disabled={disabled}>
        {cancelLabel}
      </Button>
      {changesSaved && (
        <div tabIndex={-1} ref={forwardedRef} className={styles.changesSavedConfirmation}>
          <Octicon icon={CheckIcon} size="small" className={styles.successCheckIcon} />
          <span className={styles.confirmationMessage}>{Resources.changesSavedText}</span>
        </div>
      )}
    </div>
  )
}
