import {FormControl, TextInput} from '@primer/react'

import {ISSUE_TYPE_NAME_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import styles from './TypeName.module.css'

type TypeTitleProps = {
  disabled?: boolean
  name: string
  error: string
  setName: (name: string) => void
  setError: (error: string) => void
  ref?: React.Ref<HTMLInputElement>
}

export function TypeName({ref: forwardedRef, error, setError, name, setName, disabled = false}: TypeTitleProps) {
  return (
    <FormControl disabled={disabled} className={styles.typeNameFormControl} required>
      <FormControl.Label>{Resources.nameLabel}</FormControl.Label>
      <TextInput
        value={name}
        onChange={e => {
          setError('')
          setName(e.target.value)
        }}
        maxLength={ISSUE_TYPE_NAME_LIMIT}
        placeholder={Resources.namePlaceholder}
        name="name"
        data-testid="issue-type-name"
        validationStatus={error ? 'error' : undefined}
        ref={forwardedRef}
        className={styles.typeNameInput}
        autoFocus
      />
      {error && <FormControl.Validation variant="error">{error}</FormControl.Validation>}
    </FormControl>
  )
}
