import {type DefaultError, useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

import type {IssueType} from '../types/issue-type'

export type DeleteIssueTypeMutationResult = IssueType | {errors: string[]}

export type DeleteIssueTypeInput = {
  issueTypeId: string
}

export function useDeleteIssueTypeMutation({
  owner,
  onError,
  onSuccess,
}: {
  owner: string
  onError: (error: Error) => void
  onSuccess: (data: DeleteIssueTypeMutationResult) => void
}) {
  return useMutation<DeleteIssueTypeMutationResult, DefaultError, DeleteIssueTypeInput>({
    onError,
    onSuccess,
    mutationFn: async (payload: DeleteIssueTypeInput) => {
      const {issueTypeId} = payload
      const pathname = `/organizations/${owner}/settings/issue-types/${issueTypeId}`

      const formData = new FormData()
      formData.append('id', issueTypeId)

      const response = await reactFetch(pathname, {
        method: 'DELETE',
        body: formData,
      })

      return (await response.json()) as DeleteIssueTypeMutationResult
    },
  })
}
